  return [...mensajes]
    .sort((a, b) => a.n - b.n)
    .map((m) => {
      const hora = String(m.timestamp).slice(11, 19); // HH:MM:SS de YYYY-MM-DDTHH:MM:SS
      const texto = String(m.texto).replace(/\s*\r?\n\s*/g, ' ');
      return `[${m.n}] ${hora} ${m.emisor}: ${texto}`;
    })
    .join('\n');
