    `numero_caso: ${metadatos.numero_caso === null ? 'sin caso' : metadatos.numero_caso}`,
    `estado_caso: ${metadatos.estado_caso}`,
    `escalado: ${metadatos.escalado ? 'si' : 'no'}`,
    `campos_capturados: ${campos}`,
  ].join(' | ');
